describe('User Profile - Update Display Name', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!',
    originalName: 'John Doe',
    newName: 'Jane Smith',
    updatedName: 'Jane Smith Updated'
  };

  beforeEach(() => {
    cy.visit('/');
    cy.clearCookies();
    cy.clearLocalStorage();

    // Login
    cy.get('[data-testid="login-email"]').type(testUser.email);
    cy.get('[data-testid="login-password"]').type(testUser.password);
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
  });

  it('should update display name and reflect changes across the app', () => {
    // Navigate to profile settings
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();
    cy.get('[data-testid="profile-page-title"]').should('contain', 'Profile Settings');

    // Verify current display name
    cy.get('[data-testid="display-name-input"]').should('have.value', testUser.originalName);

    // Update display name
    cy.get('[data-testid="display-name-input"]').clear().type(testUser.newName);
    cy.get('[data-testid="save-profile-button"]').click();

    // Verify success message
    cy.get('[data-testid="success-toast"]').should('contain', 'Profile updated successfully');
    cy.get('[data-testid="success-toast"]').should('be.visible');

    // Verify name is updated in profile page
    cy.get('[data-testid="display-name-input"]').should('have.value', testUser.newName);

    // Navigate to dashboard and verify name is reflected in header
    cy.get('[data-testid="dashboard-link"]').click();
    cy.get('[data-testid="user-display-name-header"]').should('contain', testUser.newName);

    // Navigate to another section and verify persistence
    cy.get('[data-testid="messages-link"]').click();
    cy.get('[data-testid="user-display-name-header"]').should('contain', testUser.newName);

    // Go back to profile and verify the change persisted
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();
    cy.get('[data-testid="display-name-input"]').should('have.value', testUser.newName);
  });

  it('should handle edge cases when updating display name with special characters and max length', () => {
    // Navigate to profile settings
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();

    // Test with special characters
    const specialCharName = "Jean-Pierre O'Brien";
    cy.get('[data-testid="display-name-input"]').clear().type(specialCharName);
    cy.get('[data-testid="save-profile-button"]').click();
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="display-name-input"]').should('have.value', specialCharName);

    // Test with maximum length name (assuming 50 char limit)
    const maxLengthName = 'A'.repeat(50);
    cy.get('[data-testid="display-name-input"]').clear().type(maxLengthName);
    cy.get('[data-testid="save-profile-button"]').click();
    cy.get('[data-testid="success-toast"]').should('be.visible');

    // Test that exceeding max length is prevented
    cy.get('[data-testid="display-name-input"]').clear().type('A'.repeat(51));
    cy.get('[data-testid="display-name-input"]').should('have.value', 'A'.repeat(50));

    // Test with empty name should show validation error
    cy.get('[data-testid="display-name-input"]').clear();
    cy.get('[data-testid="save-profile-button"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Display name is required');
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Test with whitespace only
    cy.get('[data-testid="display-name-input"]').type('   ');
    cy.get('[data-testid="save-profile-button"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Display name cannot be empty');
  });

  it('should handle concurrent updates and show appropriate feedback', () => {
    cy.get('[data-testid="user-menu-button"]').click();
    cy.get('[data-testid="profile-settings-link"]').click();

    // Update name
    cy.get('[data-testid="display-name-input"]').clear().type(testUser.updatedName);

    // Click save and verify loading state
    cy.get('[data-testid="save-profile-button"]').click();
    cy.get('[data-testid="save-profile-button"]').should('be.disabled');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Wait for success
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="save-profile-button"]').should('not.be.disabled');

    // Verify final state
    cy.get('[data-testid="display-name-input"]').should('have.value', testUser.updatedName);
  });
});
